1	// Package config reads the service configuration from the environment.
2	package config
3	
4	import (
5		"fmt"
6		"os"
7		"strings"
8	)
9	
10	// Config is everything the service needs to start.
11	type Config struct {
12		// Addr is the listen address, host:port.
13		Addr string
14		// DBPath is where the store persists, or "" for memory only.
15		DBPath string
16		// LogLevel is one of debug, info, warn, error.
17		LogLevel string
18	}
19	
20	// Defaults are used for every variable that is unset.
21	var Defaults = Config{Addr: ":8080", DBPath: "", LogLevel: "info"}
22	
23	// Load reads SVC_ADDR, SVC_DB and SVC_LOG_LEVEL, falling back to Defaults,
24	// and validates the result.
25	func Load() (Config, error) {
26		c := Defaults
27		if v := os.Getenv("SVC_ADDR"); v != "" {
28			c.Addr = v
29		}
30		if v := os.Getenv("SVC_DB"); v != "" {
31			c.DBPath = v
32		}
33		if v := os.Getenv("SVC_LOG_LEVEL"); v != "" {
34			c.LogLevel = strings.ToLower(v)
35		}
36		if err := c.Validate(); err != nil {
37			return Config{}, err
38		}
39		return c, nil
40	}
41	
42	// Validate checks the values without touching the environment.
43	func (c Config) Validate() error {
44		if c.Addr == "" || !strings.Contains(c.Addr, ":") {
45			return fmt.Errorf("config: SVC_ADDR %q must be host:port", c.Addr)
46		}
47		switch c.LogLevel {
48		case "debug", "info", "warn", "error":
49		default:
50			return fmt.Errorf("config: SVC_LOG_LEVEL %q must be debug, info, warn or error", c.LogLevel)
51		}
52		return nil
53	}

1	// Package server is the HTTP face of the service.
2	package server
3	
4	import (
5		"log"
6		"net/http"
7		"time"
8	
9		"example.com/svc/config"
10		"example.com/svc/store"
11	)
12	
13	// Server wraps the handlers and their dependencies.
14	type Server struct {
15		cfg   config.Config
16		store store.Store
17		log   *log.Logger
18	}
19	
20	// New builds a Server over st.
21	func New(cfg config.Config, st store.Store, logger *log.Logger) *Server {
22		if logger == nil {
23			logger = log.Default()
24		}
25		return &Server{cfg: cfg, store: st, log: logger}
26	}
27	
28	// Handler is the routed HTTP handler with logging applied.
29	func (s *Server) Handler() http.Handler {
30		mux := http.NewServeMux()
31		mux.HandleFunc("GET /items", s.listItems)
32		mux.HandleFunc("POST /items", s.createItem)
33		mux.HandleFunc("GET /items/{id}", s.getItem)
34		mux.HandleFunc("DELETE /items/{id}", s.deleteItem)
35		return s.logged(mux)
36	}
37	
38	// HTTPServer is an http.Server bound to the configured address with the
39	// service's timeouts.
40	func (s *Server) HTTPServer() *http.Server {
41		return &http.Server{
42			Addr:         s.cfg.Addr,
43			Handler:      s.Handler(),
44			ReadTimeout:  10 * time.Second,
45			WriteTimeout: 10 * time.Second,
46		}
47	}
48	
49	// logged records one line per request at info level or above.
50	func (s *Server) logged(next http.Handler) http.Handler {
51		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
52			start := time.Now()
53			rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
54			next.ServeHTTP(rec, r)
55			if s.cfg.LogLevel == "debug" || s.cfg.LogLevel == "info" {
56				s.log.Printf("%s %s %d %s", r.Method, r.URL.Path, rec.status, time.Since(start).Round(time.Millisecond))
57			}
58		})
59	}
60	
61	type statusRecorder struct {
62		http.ResponseWriter
63		status int
64	}
65	
66	func (r *statusRecorder) WriteHeader(code int) {
67		r.status = code
68		r.ResponseWriter.WriteHeader(code)
69	}

1	// Package store keeps items. The only implementation today is in memory;
2	// the interface is what the server programs against.
3	package store
4	
5	import (
6		"errors"
7		"sort"
8		"sync"
9		"time"
10	)
11	
12	// Item is one stored record.
13	type Item struct {
14		ID      string    `json:"id"`
15		Name    string    `json:"name"`
16		Tags    []string  `json:"tags,omitempty"`
17		Created time.Time `json:"created"`
18	}
19	
20	// ErrNotFound is returned for an unknown id.
21	var ErrNotFound = errors.New("store: not found")
22	
23	// ErrExists is returned when an id is already taken.
24	var ErrExists = errors.New("store: already exists")
25	
26	// Store is what the server needs from a backend.
27	type Store interface {
28		Put(item Item) error
29		Get(id string) (Item, error)
30		List() []Item
31		Delete(id string) error
32	}
33	
34	// MemStore is a Store held in a map, safe for concurrent use.
35	type MemStore struct {
36		mu    sync.RWMutex
37		items map[string]Item
38	}
39	
40	// NewMemStore returns an empty MemStore.
41	func NewMemStore() *MemStore {
42		return &MemStore{items: map[string]Item{}}
43	}
44	
45	// Put stores a new item; it fails if the id exists.
46	func (s *MemStore) Put(item Item) error {
47		if item.ID == "" {
48			return errors.New("store: empty id")
49		}
50		s.mu.Lock()
51		defer s.mu.Unlock()
52		if _, ok := s.items[item.ID]; ok {
53			return ErrExists
54		}
55		if item.Created.IsZero() {
56			item.Created = time.Now().UTC()
57		}
58		s.items[item.ID] = item
59		return nil
60	}
61	
62	// Get returns the item with id.
63	func (s *MemStore) Get(id string) (Item, error) {
64		s.mu.RLock()
65		defer s.mu.RUnlock()
66		it, ok := s.items[id]
67		if !ok {
68			return Item{}, ErrNotFound
69		}
70		return it, nil
71	}
72	
73	// List returns every item sorted by id.
74	func (s *MemStore) List() []Item {
75		s.mu.RLock()
76		defer s.mu.RUnlock()
77		out := make([]Item, 0, len(s.items))
78		for _, it := range s.items {
79			out = append(out, it)
80		}
81		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
82		return out
83	}
84	
85	// Delete removes the item with id.
86	func (s *MemStore) Delete(id string) error {
87		s.mu.Lock()
88		defer s.mu.Unlock()
89		if _, ok := s.items[id]; !ok {
90			return ErrNotFound
91		}
92		delete(s.items, id)
93		return nil
94	}
95	
96	// Len is the number of items, for tests and metrics.
97	func (s *MemStore) Len() int {
98		s.mu.RLock()
99		defer s.mu.RUnlock()
100		return len(s.items)
101	}

