// and validates the result.
func Load() (Config, error) {
	c := Defaults
	if v := os.Getenv("SVC_ADDR"); v != "" {
		c.Addr = v
	}
	if v := os.Getenv("SVC_DB"); v != "" {
		c.DBPath = v
	}
	if v := os.Getenv("SVC_LOG_LEVEL"); v != "" {
		c.LogLevel = strings.ToLower(v)
	}
	if v := os.Getenv("SVC_TIMEOUT"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			return Config{}, fmt.Errorf("config: SVC_TIMEOUT %q is not a valid duration: %w", v, err)
		}
		c.Timeout = d
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

