12	func (s *Server) listItems(w http.ResponseWriter, r *http.Request) {
13		items := s.store.List()
14		if tag := r.URL.Query().Get("tag"); tag != "" {
15			var kept []store.Item
16			for _, it := range items {
17				for _, t := range it.Tags {
18					if t == tag {
19						kept = append(kept, it)
20						break
21					}
22				}
23			}
24			items = kept
25		}
26		writeJSON(w, http.StatusOK, items)
27	}
28	
29	func (s *Server) createItem(w http.ResponseWriter, r *http.Request) {
30		var in store.Item
31		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
32			writeError(w, http.StatusBadRequest, "invalid JSON: "+err.Error())
33			return
34		}
35		in.ID = strings.TrimSpace(in.ID)
36		in.Name = strings.TrimSpace(in.Name)
37		if in.ID == "" || in.Name == "" {
38			writeError(w, http.StatusBadRequest, "id and name are required")
39			return
40		}
41		if err := s.store.Put(in); err != nil {
42			if errors.Is(err, store.ErrExists) {
43				writeError(w, http.StatusConflict, err.Error())
44				return
45			}
46			writeError(w, http.StatusInternalServerError, err.Error())
47			return
48		}
49		it, _ := s.store.Get(in.ID)
50		writeJSON(w, http.StatusCreated, it)
51	}
52	
53	func (s *Server) getItem(w http.ResponseWriter, r *http.Request) {
54		it, err := s.store.Get(r.PathValue("id"))
55		if errors.Is(err, store.ErrNotFound) {
56			writeError(w, http.StatusNotFound, "no such item")
57			return
58		}
59		writeJSON(w, http.StatusOK, it)
60	}
61	
62	func (s *Server) deleteItem(w http.ResponseWriter, r *http.Request) {
63		if err := s.store.Delete(r.PathValue("id")); errors.Is(err, store.ErrNotFound) {
64			writeError(w, http.StatusNotFound, "no such item")
65			return
66		}
67		w.WriteHeader(http.StatusNoContent)
68	}
69	
70	func writeJSON(w http.ResponseWriter, status int, v any) {
71		w.Header().Set("Content-Type", "application/json")
72		w.WriteHeader(status)
73		_ = json.NewEncoder(w).Encode(v)
74	}
75	
76	func writeError(w http.ResponseWriter, status int, msg string) {
77		writeJSON(w, status, map[string]string{"error": msg})
