1	// Package server is the HTTP face of the service.
2	package server
3	
4	import (
5		"log"
6		"net/http"
7		"time"
8	
9		"example.com/svc/config"
10		"example.com/svc/store"
11	)
12	
13	// Server wraps the handlers and their dependencies.
14	type Server struct {
15		cfg   config.Config
16		store store.Store
17		log   *log.Logger
18	}
19	
20	// New builds a Server over st.
21	func New(cfg config.Config, st store.Store, logger *log.Logger) *Server {
22		if logger == nil {
23			logger = log.Default()
24		}
25		return &Server{cfg: cfg, store: st, log: logger}
26	}
27	
28	// Handler is the routed HTTP handler with logging applied.
29	func (s *Server) Handler() http.Handler {
30		mux := http.NewServeMux()
31		mux.HandleFunc("GET /items", s.listItems)
32		mux.HandleFunc("POST /items", s.createItem)
33		mux.HandleFunc("GET /items/{id}", s.getItem)
34		mux.HandleFunc("DELETE /items/{id}", s.deleteItem)
35		return s.logged(mux)
36	}
37	
38	// HTTPServer is an http.Server bound to the configured address with the
39	// service's timeouts.
40	func (s *Server) HTTPServer() *http.Server {
41		return &http.Server{
42			Addr:         s.cfg.Addr,
43			Handler:      s.Handler(),
44			ReadTimeout:  s.cfg.Timeout,
45			WriteTimeout: s.cfg.Timeout,
46		}
47	}
48	
49	// logged records one line per request at info level or above.
50	func (s *Server) logged(next http.Handler) http.Handler {
51		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
52			start := time.Now()
53			rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
54			next.ServeHTTP(rec, r)
55			if s.cfg.LogLevel == "debug" || s.cfg.LogLevel == "info" {
56				s.log.Printf("%s %s %d %s", r.Method, r.URL.Path, rec.status, time.Since(start).Round(time.Millisecond))
57			}
58		})
59	}
60	
61	type statusRecorder struct {
62		http.ResponseWriter
63		status int
64	}
65	
66	func (r *statusRecorder) WriteHeader(code int) {
67		r.status = code
68		r.ResponseWriter.WriteHeader(code)
69	}

